/* Элемент минимум 200px, даже если flex-shrink: 1 */
.item {
  flex: 1;
  min-width: 200px;
}

/* Элемент максимум 500px, даже если flex-grow: 3 */
.item {
  flex: 3;
  max-width: 500px;
}

/* Центрирование по обеим осям */
.container {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Тот же результат через auto margin */
.item {
  margin: auto;
}

/* Разнести элементы: один влево, другой вправо */
.item-left { margin-right: auto; }
.item-right { margin-left: auto; }

/* Один элемент внизу, остальные наверху */
.container {
  display: flex;
  align-items: flex-start;
  height: 300px;
}

.container .bottom-item {
  align-self: flex-end;
}

/* Выравнивание строк при переносе */
.container {
  flex-wrap: wrap;
  align-content: center; /* строки по центру */
}

.layout {
  display: grid;
  grid-template-areas:
    "header header header"
    "sidebar main   main"
    "footer footer footer";
  grid-template-columns: 200px 1fr 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
}

.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.footer  { grid-area: footer; }

/* Через имя */
.header { grid-area: header; }

/* Через линии: grid-row / grid-column */
.item { grid-area: 1 / 1 / 2 / 3; }
/* строка 1-2, колонка 1-3 */

/* auto-fill: создаёт столько колонок, сколько помещается */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 16px;
}

/* auto-fit: то же, но пустые колонки сжимаются до 0 */
.grid {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 16px;
}

/* Явная сетка: 3 колонки */
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

/* Неявные строки будут auto-высоты */
/* Контролируйте через grid-auto-rows */
.grid {
  grid-auto-rows: minmax(100px, auto);
}

.layout {
  display: grid;
  grid-template-columns: [start] 200px [main] 1fr [end];
  grid-template-rows: [header] auto [content] 1fr [footer] auto;
}

.header {
  grid-column: start / end;
  grid-row: header;
}

.grid {
  display: grid;
  place-items: center; /* все элементы по центру */
}

.special {
  place-self: end start; /* этот элемент внизу слева */
}

.dashboard {
  display: grid;
  grid-template-areas:
    "nav    nav    nav"
    "sidebar stats  stats"
    "sidebar chart  chart"
    "sidebar table  table";
  grid-template-columns: 250px 1fr 1fr;
  grid-template-rows: 60px 1fr 1fr 1fr;
  gap: 16px;
  min-height: 100vh;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  padding: 20px;
}

.table {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1px;
  background: #ddd;
}

.table > * {
  background: white;
  padding: 12px 16px;
}

.element {
  background-color: #f0f0f0;   /* цвет фона */
  background-image: url(bg.jpg); /* изображение */
  background-size: cover;        /* размер */
  background-position: center;   /* позиция */
  background-repeat: no-repeat;  /* повторение */
  background-attachment: fixed;   /* прикрепление */
  background-origin: padding-box; /* начало координат */
  background-clip: border-box;    /* область отрисовки */
}

/* Сокращённое свойство */
.element {
  background: #f0f0f0 url(bg.jpg) center/cover no-repeat;
}

/* cover: заполнить весь элемент, обрезать лишнее */
.hero {
  background-size: cover;
}

/* contain: вписать целиком, могут быть полосы */
.logo {
  background-size: contain;
}

/* Конкретные размеры */
.icon {
  background-size: 32px 32px;
}

/* Проценты */
.pattern {
  background-size: 50% auto;
}

/* Ключевые слова */
.bg { background-position: center top; }
.bg { background-position: right bottom; }

/* Проценты */
.bg { background-position: 50% 50%; }

/* Пиксели */
.bg { background-position: 20px 40px; }

/* Комбинация */
.bg { background-position: right 20px bottom 10px; }

.overlay {
  background:
    linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)),
    url('/images/hero.jpg') center/cover no-repeat;
}

/* Градиент + паттерн */
.pattern {
  background:
    repeating-linear-gradient(
      45deg,
      #fff,
      #fff 10px,
      #f0f0f0 10px,
      #f0f0f0 20px
    ),
    #fff;
}

/* Фон обрезается по border-box (по умолчанию) */
.border-bg { background-clip: border-box; }

/* Фон обрезается по padding-box */
.padding-bg { background-clip: padding-box; }

/* Фон обрезается по content-box */
.content-bg { background-clip: content-box; }

/* Текст поверх градиента */
.gradient-text {
  background: linear-gradient(to right, #667eea, #764ba2);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  color: transparent;
}

/* Простой градиент */
.simple {
  background: linear-gradient(to right, #667eea, #764ba2);
}

/* С углом */
.angled {
  background: linear-gradient(135deg, #667eea, #764ba2);
}

/* Несколько цветов */
.rainbow {
  background: linear-gradient(to right, red, orange, yellow, green, blue);
}

/* Остановки */
.stop {
  background: linear-gradient(to right, #667eea 0%, #764ba2 50%, #f093fb 100%);
}

/* Простой */
.simple {
  background: radial-gradient(circle, #667eea, #764ba2);
}

/* Эллипс (по умолчанию) */
.ellipse {
  background: radial-gradient(ellipse, #667eea, #764ba2);
}

/* Размер */
.sized {
  background: radial-gradient(circle 100px, #667eea, #764ba2);
}

/* Позиция */
.positioned {
  background: radial-gradient(circle at top left, #667eea, #764ba2);
}

/* Простой conic */
.simple {
  background: conic-gradient(red, orange, yellow, green, blue);
}

/* С позицией */
.positioned {
  background: conic-gradient(from 0deg at 50% 50%, red, blue);
}

/* Повторяющийся */
.repeating {
  background: repeating-conic-gradient(
    #eee 0% 25%, white 0% 50%
  ) 50% / 20px 20px;
}

